import { decodeRevertReason } from './reason-map.js';
// Native VRF funding is real network ETH, independent of the game's testnet ETH divisor.
import { CONTRACTS } from './chain-config.js';
import { ethers, getProvider, sendTx } from './contracts.js';
import { get } from './store.js';
import { register } from './reason-map.js';
import { permissionlessReadProvider, readProviderBlockNumber } from './read-provider.js';

const ADMIN_ABI = [
  'function donateVrf() payable',
  'function coordinator() view returns (address)',
  'function subscriptionId() view returns (uint256)',
  'error InvalidAmount()', 'error NoSubscription()', 'error GameOver()',
];
const GAME_ABI = ['function middayRngCredits(address) view returns (uint256)', 'function gameOver() view returns (bool)'];
const COORDINATOR_ABI = ['function getSubscription(uint256) view returns (uint96 balance,uint96 nativeBalance,uint64 reqCount,address owner,address[] consumers)'];
for (const [name, message] of Object.entries({
  InvalidAmount: 'Enter a positive ETH donation.',
  NoSubscription: 'Randomness funding is not available until the subscription is configured.',
  GameOver: 'This game has ended. Randomness donations are closed.',
})) {
  const mapping = {code:name, userMessage:message, recoveryAction:'Refresh the game state.'};
  register(name, mapping);
  register(ethers.id(`${name}()`).slice(0,10), mapping);
}
let factory = null;
const contract = (address, abi, runner) => factory ? factory(address, abi, runner) : new ethers.Contract(address, abi, runner);

export function vrfDonationCredit(amount) {
  const value = BigInt(amount);
  if (value < 0n) throw new RangeError('Donation must be nonnegative.');
  return value / 4n;
}
export function middayRequestCharge(basefee) {
  const fee = BigInt(basefee);
  return 300_000n * ((fee < 10_000_000n ? 10_000_000n : fee) + 250_000_000n) * 2n;
}
export async function readVrfDonationState({ player = get('connected.address') } = {}) {
  if (!player || !CONTRACTS.GAME || !CONTRACTS.ADMIN) return null;
  const provider = permissionlessReadProvider(getProvider());
  if (!provider) return null;
  const blockTag = await readProviderBlockNumber(provider);
  const game = contract(CONTRACTS.GAME, GAME_ABI, provider);
  const admin = contract(CONTRACTS.ADMIN, ADMIN_ABI, provider);
  const [balanceWei, creditWei, gameOver, coordinator, subscriptionId] = await Promise.all([
    provider.getBalance(player, blockTag), game.middayRngCredits(player, { blockTag }),
    game.gameOver({ blockTag }), admin.coordinator({ blockTag }), admin.subscriptionId({ blockTag }),
  ]);
  let subscriptionBalanceWei = null;
  if (BigInt(subscriptionId) > 0n) {
    try {
      const subscription = await contract(coordinator, COORDINATOR_ABI, provider).getSubscription(subscriptionId, { blockTag });
      subscriptionBalanceWei = BigInt(subscription.nativeBalance ?? subscription[1]);
    } catch { /* Credit and wallet balance remain useful when coordinator reads fail. */ }
  }
  return { balanceWei: BigInt(balanceWei), creditWei: BigInt(creditWei), subscriptionBalanceWei,
    gameOver: Boolean(gameOver), subscriptionReady: BigInt(subscriptionId) > 0n };
}

export async function donateVrf({ amount } = {}) {
  let value;
  try { value = BigInt(amount); } catch { throw new Error('Enter an ETH amount to donate.'); }
  if (value <= 0n) throw new Error('Enter an ETH amount to donate.');
  if (!CONTRACTS.ADMIN) throw new Error('Randomness funding is not configured.');
  const provider = getProvider();
  if (!provider) throw new Error('Connect a wallet first.');

  const receipt = await sendTx(s => contract(CONTRACTS.ADMIN, ADMIN_ABI, s).donateVrf({ value }), 'Fund game randomness');
  return { receipt, amountWei: value, creditWei: vrfDonationCredit(value) };
}
export function __setVrfDonationContractFactoryForTest(value) { factory = value; }
